mapper.select:
select A.*, U.nickname as username, U.avatar, C.title, C.cover from b_comment as A left join b_user as U on (A.from_user_id = U.id) left join b_task as C on (A.task_id = C.id)
A.task_id = #{taskId}
order by A.like_count desc order by A.comment_time desc

select A.*, U.nickname as username, U.avatar, C.title, C.cover
from b_comment as A
         left join b_user as U on (A.from_user_id = U.id)
         left join b_task as C on (A.task_id = C.id)

    A.from_user_id = #{userId}

order by A.comment_time desc;

select A.*, U.nickname as username, U.avatar, C.title, C.cover
from b_comment as A
         left join b_user as U on (A.from_user_id = U.id)
         left join b_task as C on (A.task_id = C.id)

    A.to_user_id = #{userId}

order by A.comment_time desc;
